"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[835],{5492:function(e,a,i){i.d(a,{W:function(){return t}});let t=[{slug:"accessibility",title:"Accessibility",image:"/images/accessibility/accessibility-inauguration-ceremony.jpg",summary:"Sangati Durlabh Shauchalaya accessible toilets, railway hub transformations, tactile paving, and public space audits.",fullContent:'Sangati Foundation tears down physical and infrastructural barriers across public transit, highway toilets, and community spaces. In collaboration with Yatra and Anuprayaas, we made Hazrat Nizamuddin railway station accessible for both locomotor and visual disabilities. On 3 December 2020 (International Day of Persons with Disabilities), we inaugurated our first "Sangati Durlabh Shauchalaya" wheelchair-accessible public toilet in Sector 29, Gurgaon. We are actively expanding our campaign to build over 100 accessible highway toilets across India.',highlights:["Sangati Durlabh Shauchalaya: Wheelchair-accessible public toilets launched Sector 29, Gurgaon (3 Dec 2020)","Hazrat Nizamuddin Railway Station: Accessible transit transformation for locomotor & visual disabilities","100+ Highway Accessible Toilets Drive across national highways","Ramp design, tactile paving, grab bar installation, and universal accessibility audits"],keyStats:["Sector 29 Gurgaon Toilet","100+ Toilet Drive","Hazrat Nizamuddin Hub"],partners:["Yatra","Anuprayaas","Sangati Mobility Network"],gallery:[{id:"acc-1",title:"Sector 29 Gurgaon Accessible Toilet Inauguration Ceremony",src:"/images/accessibility/accessibility-inauguration-ceremony.jpg",caption:"Ribbon-cutting launch ceremony of Sangati Durlabh Shauchalaya on 3 Dec 2020 (International Day of Persons with Disabilities)."},{id:"acc-2",title:"Sangati Durlabh Shauchalaya Accessible Toilet Cabin",src:"/images/accessibility/accessibility-durlabh-shauchalaya.jpg",caption:"Outdoor wheelchair-accessible toilet cabin with custom ramps and grab bars deployed by Sangati Foundation."},{id:"acc-3",title:"Universal Accessible Toilet Signage & Branding",src:"/images/accessibility/accessibility-toilet-signage.jpg",caption:"Universal male, female, and wheelchair accessibility signage on Sangati Foundation public facilities."}]},{slug:"mobility",title:"Mobility",image:"/images/programs/program-mobility.jpg",summary:"Modified vehicles, folding ramps, accessible cabs, and Nomads on Wheels to unlock independent travel.",fullContent:"Modified vehicles, folding ramps, wheelchair-accessible cabs, and Nomads on Wheels — our campaign to make tourism across India genuinely reachable. Travel options, boarding, lodging, restaurants, markets, theatres, monuments: each one checked for accessibility and sensitised to the need.",highlights:["Nomads on Wheels: Nationwide accessible tourism campaign","Custom vehicle retrofitting and hand-controls advocacy","Accessible transport directory: hotels, restaurants, theatres, monuments","Door-to-door wheelchair folding ramp provision"],keyStats:["6,500 km Yatra Route Covered","100s of Verified Accessible Sites","24/7 Helpline Support"],partners:["Nomads on Wheels","Sangati Mobility Network"]},{slug:"health",title:"Health & Critical Care",image:"/images/health/health-cancer-van-team.jpg",summary:"Rural OPD care in Himachal Pradesh, Asha Kiran mobile cancer screening camps, mammography, and medical aid.",fullContent:"Sangati Foundation organizes free cancer screening, health check-up, and awareness camps in partnership with the Indian Cancer Society, IDSIL, and Engineers India Limited (EIL). Utilizing the Asha Kiran Mobile Cancer Detection Van equipped with digital X-ray, mammography, and diagnostic facilities, we screen rural and marginalized populations. Our critical care center in Bathri, Dalhousie, HP also serves 300 OPD patients daily with consultation, maternal care, and emergency aid.",highlights:["Asha Kiran Mobile Cancer Detection Van: Mammography, Pap Smear, Digital X-Ray, & ENT checks","Free Cancer Screening & Awareness Camps in partnership with Indian Cancer Society & IDSIL","Winter Warmth & Relief Drives: Distribution of warm sweaters, blankets, and essential winter wear to wheelchair users & PwD families","Bathri Critical Care Centre (Dalhousie, HP): 300 OPD patients served daily","Specialized focus on women health (over 80% female beneficiaries in screening camps)"],keyStats:["300 Daily OPD Patients","140+ Cancer Screenings","Winter Warmth Drives"],partners:["Indian Cancer Society","Engineers India Limited (EIL)","Disabled Employees Assoc. of Railways","IDSIL"],gallery:[{id:"hl-1",title:"Asha Kiran Mobile Cancer Detection Van & Sangati Team",src:"/images/health/health-cancer-van-team.jpg",caption:"Sangati Foundation volunteers and doctors in front of the Asha Kiran Mobile Cancer Detection Van during the screening drive."},{id:"hl-2",title:"Winter Sweater & Blanket Giveaway for Wheelchair Users",src:"/images/health/health-winter-blanket-wheelchair.jpg",caption:"Sangati representative handing warm winter blankets and sweaters directly to a wheelchair beneficiary (Disabled Employees Assoc. of Railways)."},{id:"hl-3",title:"Winter Relief Distribution Drive for PwD Families",src:"/images/health/health-winter-relief-distribution.jpg",caption:"Sangati team distributing stacks of colorful warm winter blankets, shawls, and sweaters at an outdoor community relief drive."},{id:"hl-4",title:"Winter Warmth Relief Preparation & Stacks",src:"/images/health/health-winter-blankets-stack.jpg",caption:"Stacks of warm winter blankets and sweaters organized for distribution to PwD beneficiaries."},{id:"hl-5",title:"Doctor Performing OPD Medical Examination",src:"/images/health/health-opd-checkup.jpg",caption:"Medical doctor examining a patient during the free rural health check-up camp."},{id:"hl-6",title:"Sangati Free Cancer Screening & Awareness Camp Team",src:"/images/health/health-camp-banner-group.jpg",caption:"Group photo of Sangati Foundation, Indian Cancer Society, and IDSIL volunteers at the medical camp."},{id:"hl-7",title:"Accessible Asha Kiran Mobile Medical Van with Ramp",src:"/images/health/health-mobile-van-ramp.jpg",caption:"The wheel-accessible Asha Kiran Cancer Detection Mobile Van equipped for specialized diagnostic screenings."}]},{slug:"skills",title:"Skill Development & Jobs",image:"/images/skills/skill-bakery-mandi-group.jpg",summary:"Project Udaan: Free skill training in Bakery & Culinary Arts, RPL Pump Operator, Laptop Repair, Web Dev, Python, DTP, and placement support.",fullContent:"Under Project Udaan, Sangati runs free skill development and vocational training for persons with disability (PwD) and Below Poverty Line (BPL) candidates across Himachal Pradesh (Mandi & Kangra) and Delhi NCR. Initiatives include Bakery & Pastry Training, RPL Pump Operator Certification under State Sanitation Mission, Laptop Repair with CompTIA A+ certification, Web Development, and DTP. Delivered at our centers with partners including Charities Aid Foundation, State Sanitation Mission HP, and Sh Praveen Vyas (Jodhpur Center). Our job portal helps candidates prepare, interview and secure sustainable livelihoods with ongoing mentorship.",highlights:["Project Udaan Bakery & Pastry Training for PwD & BPL candidates in Mandi (HP)","RPL Pump Operator Training in District Kangra (HP) under State Sanitation Mission","Free certification in Laptop Repair (CompTIA A+), Web Dev, Python, & DTP","Dedicated Job Portal & post-placement mentorship for independent living"],keyStats:["170+ Certified Trainees","Mandi & Kangra Centers","100% Free Tuition"],partners:["Charities Aid Foundation","State Sanitation Mission HP","CompTIA","JetKing"],gallery:[{id:"sk-1",title:"Project Udaan Bakery Training Graduation (Mandi, HP)",src:"/images/skills/skill-bakery-mandi-group.jpg",caption:"Group photo of PwD & BPL trainees receiving Sangati Skill Development Certificates in Mandi, Himachal Pradesh."},{id:"sk-2",title:"Wheelchair Beneficiary Receiving Bakery Certificate",src:"/images/skills/skill-bakery-wheelchair.jpg",caption:"Wheelchair beneficiary proudly holding his Bakery & Pastry Training Certificate at Sangati Skill Development Center, Mandi."},{id:"sk-3",title:"Sangati Skill Certificate Distribution Ceremony",src:"/images/skills/skill-cert-ceremony.png",caption:"Women trainees receiving their Sangati Foundation Skill Certificates during the graduation ceremony."},{id:"sk-4",title:"Graduating Class of Tech & Repair Skill Trainees",src:"/images/skills/skill-classroom-group.jpg",caption:"Group photo of young men and women celebrating their skill certification at Sangati Foundation."},{id:"sk-5",title:"RPL Pump Operator Training Session (Kangra, HP)",src:"/images/skills/skill-kangra-training.png",caption:"Classroom training session for Pump Operator certification under State Sanitation Mission in Kangra, Himachal Pradesh."}]},{slug:"livelihood",title:"Livelihood & Entrepreneurship",image:"/images/livelihood/ekart-shoppe-sidecar.jpg",summary:"Sangati Shoppe (संगTea) custom retrofitted e-karts and mobile vendor carts for PwD economic self-reliance and dignity.",fullContent:"Sangati Shoppe is a custom-designed, accessible mobile street vendor cart — संगTea — built specifically so that persons with disability (PwD) can own and operate micro-businesses independently and with utmost dignity. Featuring retrofitted motorized 3-wheelers, sidecars, gas stoves, beverage coolers, and commodity display racks, Sangati Foundation partners with Evoo (VentureonWheels) and NHFDC to empower micro-entrepreneurs across urban and rural markets.",highlights:["संगTea / Sangati Shoppe: Custom ergonomic motorized e-karts & sidecars for Divyang entrepreneurs","Turnkey micro-business setup: Built-in tea stoves, beverage coolers, and commodity display racks","Keys handover, licensing guidance, and financial independence mentorship","VentureonWheels partnership with Evoo and NHFDC handicraft showcase at Divyakala Mela"],keyStats:["Independent E-Kart Businesses","NHFDC Handicraft Partner","VentureonWheels Carts"],partners:["NHFDC","Evoo (VentureonWheels)","Sangati Shoppe Network"],gallery:[{id:"lv-1",title:"Sangati Shoppe Retrofitted Electric Vendor Sidecar Cart",src:"/images/livelihood/ekart-shoppe-sidecar.jpg",caption:"Micro-entrepreneurs operating their Sangati Shoppe custom retrofitted motorized sidecar vendor cart."},{id:"lv-2",title:"संगTea Mobile Cart Keys Handover to Female PwD Entrepreneur",src:"/images/livelihood/ekart-sangtea-key-handover.png",caption:"Official keys handover ceremony of the sangTea motorized tricycle cart to an empowered female entrepreneur."},{id:"lv-3",title:"Sangati Shoppe Ergonomic Mobile Tea & Snack Stall",src:"/images/livelihood/ekart-shoppe-tea-stall.jpg",caption:"Divyang vendor operating a fully equipped mobile tea stall with gas stove, kettles, and storage shelves."},{id:"lv-4",title:"Maroon Motorized 3-Wheel Vendor Cart for Divyang Entrepreneurs",src:"/images/livelihood/ekart-shoppe-maroon-trike.jpg",caption:"Entrepreneur on his customized maroon motorized 3-wheeler fitted with snack display racks."},{id:"lv-5",title:"Sangati Shoppe Accessible Mobile Vendor Unit with Cooler",src:"/images/livelihood/ekart-shoppe-street-vendor.png",caption:"Street vendor unit featuring Coca-Cola cooler box and hanging commodity display strips on city road."}]},{slug:"para-sports",title:"Para Sports & Adaptive Yoga",image:"/images/parasports/parasports-india-gate-yoga.jpg",summary:"Accessible Yoga at India Gate with Ministry of Ayush, Wheelchair Cricket Champions, Half-Marathon runners, and adaptive athletics.",fullContent:'Sangati Foundation actively champions Para Sports, Wheelchair Athletics, and Accessible Fitness across India. On International Yoga Day at India Gate, New Delhi, in collaboration with the Ministry of Ayush (Govt. of India), Eagle Specially Abled Riders, and Kaner Electric Connections, our Divyang athletes and retrofitted scooter riders made history by demonstrating Accessible Yoga ("सुगम्य योग"). We also sponsor Wheelchair Cricket tournaments (Delhi Abled & Wheelchair Cricket Warriors), field teams for the Vedanta Delhi Half-Marathon (Champions with Disability segment), and run inclusive athletic clubs.',highlights:["Accessible Yoga at India Gate on International Yoga Day with Ministry of Ayush (Govt. of India)",'Sugamya Yoga ("सुगम्य योग") performed by Divyang athletes on retrofitted scooters and wheelchairs',"Wheelchair Cricket Warriors: Tournament sponsorship, equipment, and training support","Vedanta Delhi Half-Marathon: 25 Divyang marathon runners representing Sangati Foundation"],keyStats:["Ministry of Ayush Partner","Wheelchair Cricket Team","25+ Half-Marathon Runners"],partners:["Ministry of Ayush (Govt. of India)","Eagle Specially Abled Riders","Kaner Electric Connections","Wheelchair Cricket Association"],gallery:[{id:"ps-1",title:"Accessible Yoga at India Gate (Ministry of Ayush)",src:"/images/parasports/parasports-india-gate-yoga.jpg",caption:"Divyang athletes and wheelchair participants performing Accessible Yoga at India Gate on International Yoga Day."},{id:"ps-2",title:"Wheelchair Cricket Warriors Tournament",src:"/images/parasports/parasports-wheelchair-cricket.jpg",caption:"Divyang wheelchair cricket players and coaches shaking hands on the pitch during an official match."},{id:"ps-3",title:"National Media Feature: Sugamya Yoga on Retrofitted Scooters",src:"/images/parasports/parasports-yoga-news-clipping.jpg",caption:'Front-page news feature ("एक नई क्रांति न्यूज़") highlighting Accessible Yoga on retrofitted scooters at India Gate.'},{id:"ps-4",title:"Outdoor Accessible Yoga Masterclass Session",src:"/images/parasports/parasports-outdoor-yoga-session.png",caption:"Yoga Guru Sandeep Kumar conducting an outdoor accessible yoga training session under the trees."},{id:"ps-5",title:"Sangati Para Athletes & Retrofitted Scooter Riders Group",src:"/images/parasports/parasports-riders-group.jpg",caption:"Group photo of Sangati Para Athletes and scooter riders gathering after their yoga and sports session."}]}]},3145:function(e,a,i){i.d(a,{default:function(){return n.a}});var t=i(8461),n=i.n(t)},8461:function(e,a,i){Object.defineProperty(a,"__esModule",{value:!0}),function(e,a){for(var i in a)Object.defineProperty(e,i,{enumerable:!0,get:a[i]})}(a,{default:function(){return l},getImageProps:function(){return o}});let t=i(7043),n=i(5346),r=i(5878),s=t._(i(5084));function o(e){let{props:a}=(0,n.getImgProps)(e,{defaultLoader:s.default,imgConf:{deviceSizes:[640,750,828,1080,1200,1920,2048,3840],imageSizes:[16,32,48,64,96,128,256,384],path:"/_next/image",loader:"default",dangerouslyAllowSVG:!1,unoptimized:!0}});for(let[e,i]of Object.entries(a))void 0===i&&delete a[e];return{props:a}}let l=r.Image},4440:function(e,a,i){i.d(a,{ScrollProgressBar:function(){return r}});var t=i(7437),n=i(2265);let r=()=>{let[e,a]=(0,n.useState)(0);return(0,n.useEffect)(()=>{let e=()=>{let e=document.documentElement.scrollHeight-window.innerHeight;e>0&&a(window.scrollY/e*100)};return window.addEventListener("scroll",e,{passive:!0}),()=>window.removeEventListener("scroll",e)},[]),(0,t.jsx)("div",{className:"fixed top-0 left-0 right-0 h-1.5 z-50 pointer-events-none bg-mist/30",children:(0,t.jsx)("div",{className:"h-full bg-gradient-to-r from-road via-marigold to-road transition-all duration-150 ease-out shadow-sm",style:{width:"".concat(e,"%")}})})}}}]);